#!/bin/sh
set -eu
BIN=${USAGIC_BIN:-./usagic}
CC_BIN=${TEST_CC:-gcc}
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT HUP INT TERM

# Keep generated files in an isolated temporary directory.
for sample in hello variables loops structs japanese; do
  cp "examples/$sample.usagic" "$TMP/$sample.usagic"
  "$BIN" build "$TMP/$sample.usagic" -o "$TMP/$sample" --cc "$CC_BIN" >/dev/null
  "$TMP/$sample" > "$TMP/$sample.out"
done

grep -F 'ヤハ！ Hello, World!' "$TMP/hello.out" >/dev/null
grep -F '우라 remains text' "$TMP/variables.out" >/dev/null
printf '0\n1\n3\ndone\n' > "$TMP/expected"
diff -u "$TMP/expected" "$TMP/loops.out"
grep -F 'Hello, Usagi!' "$TMP/structs.out" >/dev/null
grep -F 'こんにちは、うさぎ！' "$TMP/japanese.out" >/dev/null
grep -F 'count=0' "$TMP/japanese.out" >/dev/null
grep -F 'count=2' "$TMP/japanese.out" >/dev/null
grep -F 'ヤハ！' "$TMP/japanese.out" >/dev/null
grep -F 'long long=999, long double=1.25' "$TMP/japanese.out" >/dev/null

# Korean + Japanese: comments, quoted strings and characters must be preserved.
cat > "$TMP/lex.usagic" <<'SOURCE'
#ハイ<stdio.h>
// ウラ 우라 must stay untouched
/* ハァ "하아" remains untouched */
ウ main(푸) {
    ツツ ヤ *s = "ウラ 우라 ハァ 하아";
    ヤ c = 'x';
    우라(s);
    ウラララ 0;
}
SOURCE
"$BIN" build "$TMP/lex.usagic" -o "$TMP/lex" --cc "$CC_BIN" >/dev/null
"$TMP/lex" > "$TMP/lex.out"
grep -Fx 'ウラ 우라 ハァ 하아' "$TMP/lex.out" >/dev/null
grep -F '// ウラ 우라 must stay untouched' "$TMP/lex.usagic.c" >/dev/null
grep -F '/* ハァ "하아" remains untouched */' "$TMP/lex.usagic.c" >/dev/null

# UTF-8 BOM, including a leading #include and a Korean/Japanese source keyword.
printf '\357\273\277#ハイ<stdio.h>\nウ main(プ) { ウラ("BOM works"); ウラララ 0; }\n' > "$TMP/bom.usagic"
"$BIN" build "$TMP/bom.usagic" -o "$TMP/bom" --cc "$CC_BIN" >/dev/null
test "$("$TMP/bom")" = 'BOM works'

cat > "$TMP/bad.usagic" <<'SOURCE'
#하이<stdio.h>
우 main(푸) {
  우라("missing end);
}
SOURCE
if "$BIN" transpile "$TMP/bad.usagic" -o "$TMP/bad.c" > "$TMP/error.out" 2>&1; then
  echo 'FAIL: expected unterminated literal to fail' >&2; exit 1
fi
grep -F 'unterminated literal' "$TMP/error.out" >/dev/null

# -o must not clobber an existing user file unless explicitly forced.
echo 'USER FILE - DO NOT OVERWRITE' > "$TMP/protected.c"
if "$BIN" transpile "$TMP/lex.usagic" -o "$TMP/protected.c" > "$TMP/overwrite.out" 2>&1; then
  echo 'FAIL: existing -o target was overwritten' >&2; exit 1
fi
grep -F 'USER FILE - DO NOT OVERWRITE' "$TMP/protected.c" >/dev/null
"$BIN" transpile "$TMP/lex.usagic" -o "$TMP/protected.c" --force >/dev/null
grep -F 'Generated by UsagiC' "$TMP/protected.c" >/dev/null

# Generated .usagic.c files are safely regenerated. Hand-written C is protected.
"$BIN" transpile "$TMP/lex.usagic" >/dev/null
"$BIN" transpile "$TMP/lex.usagic" >/dev/null
printf 'HAND-WRITTEN CODE\n' > "$TMP/lex.usagic.c"
if "$BIN" transpile "$TMP/lex.usagic" > "$TMP/generate.out" 2>&1; then
  echo 'FAIL: hand-written generated-path file was overwritten' >&2; exit 1
fi
grep -Fx 'HAND-WRITTEN CODE' "$TMP/lex.usagic.c" >/dev/null

# Protect source files even if --force is supplied.
if "$BIN" transpile "$TMP/lex.usagic" -o "$TMP/lex.usagic" --force > "$TMP/same.out" 2>&1; then
  echo 'FAIL: source was overwritten' >&2; exit 1
fi
grep -F '#ハイ<stdio.h>' "$TMP/lex.usagic" >/dev/null

echo "UsagiC v0.1.1 tests passed (compiler: $CC_BIN)."
